import csv
import io
import re
from collections import defaultdict
from typing import List, Dict, Any


def parse_csv(raw_csv: str):
    expected_width = 9
    header_row_count = 3

    try:
        reader = csv.reader(
            io.StringIO(raw_csv, newline=""),
            delimiter=",",
            quotechar='"',
            doublequote=True,
            strict=False,
        )
        records = list(reader)
    except csv.Error:
        records = []
        for line in raw_csv.splitlines():
            try:
                records.append(next(csv.reader([line], delimiter=",", quotechar='"')))
            except Exception:
                records.append([line])

    records = [
        row for row in records
        if row and any(str(value) != "" for value in row)
    ]

    if not records:
        return {"columns": [], "rows": []}

    def looks_like_data(value: str) -> bool:
        return bool(re.match(r"^\s*\d{1,4}[/-]\d{1,2}[/-]\d{1,4}\s*$", value or ""))

    header_start = None
    for start in range(max(0, len(records) - header_row_count + 1)):
        group = records[start:start + header_row_count]
        if len(group) != header_row_count:
            continue
        if sum(len(row) for row in group) == expected_width:
            if not looks_like_data(group[0][0] if group[0] else ""):
                header_start = start
                break

    if header_start is None:
        header_start = 0

    header_parts = []
    for row in records[header_start:header_start + header_row_count]:
        header_parts.extend(row)

    if len(header_parts) > expected_width:
        header_parts = header_parts[:expected_width]
    while len(header_parts) < expected_width:
        header_parts.append("")

    def split_to_width(row: List[str], width: int) -> List[str]:
        if len(row) >= width:
            return row

        memo = {}

        def search(index: int, remaining: int):
            key = (index, remaining)
            if key in memo:
                return memo[key]
            if index == len(row):
                result = [] if remaining == 0 else None
                memo[key] = result
                return result
            if remaining <= 0:
                memo[key] = None
                return None

            value = row[index]
            best = None

            if len(row) - index <= remaining:
                result = search(index + 1, remaining - 1)
                if result is not None:
                    best = [(value, 0)] + result

            if ";" in value:
                pieces = value.split(";")
                if len(pieces) <= remaining:
                    result = search(index + 1, remaining - len(pieces))
                    if result is not None:
                        candidate = [(piece, 1) for piece in pieces] + result
                        if best is None or sum(x[1] for x in candidate) < sum(x[1] for x in best):
                            best = candidate

            memo[key] = best
            return best

        result = search(0, width)
        if result is not None:
            return [value for value, _ in result]
        return row

    def normalize_row(row: List[str]) -> List[str]:
        row = split_to_width(list(row), expected_width)

        if len(row) > expected_width:
            row = row[:expected_width - 1] + [",".join(row[expected_width - 1:])]
        elif len(row) < expected_width:
            row = row + [""] * (expected_width - len(row))

        return row

    data_rows = []
    for row in records[header_start + header_row_count:]:
        if not row or not any(value != "" for value in row):
            continue

        first = row[0].strip().lower() if row else ""
        if len(row) == 1 and (
            first.startswith("source:")
            or first.startswith("generated:")
            or first.startswith("export:")
        ):
            continue

        data_rows.append(normalize_row(row))

    return {
        "columns": [str(value) for value in header_parts],
        "rows": [[str(value) for value in row] for row in data_rows],
    }
